// Windows' default playback devices (console, communications) and which outputs are muted - checks after StreamLite exits (4.1.1: calls must not stay on the speakers). Usage: run.ps1 DefProbe
using System.Linq; using StreamLite.Interop; class DefProbe { static void Main() { var outs = AudioDevices.List(EDataFlow.Render); System.Func<string,string> nm = id => { var d = outs.FirstOrDefault(o => o.Id == id); return d == null ? id : d.Name; }; System.Console.WriteLine("console default: " + nm(AudioDevices.GetDefaultId(EDataFlow.Render, ERole.Console))); System.Console.WriteLine("communications default: " + nm(AudioDevices.GetDefaultId(EDataFlow.Render, ERole.Communications))); foreach (var d in outs) System.Console.WriteLine("  " + d.Name + " muted=" + AudioDevices.GetMute(d.Id)); } }
